// And groups predicates with the AND operator between them.
func And(predicates ...predicate.KnowledgeAccessLog) predicate.KnowledgeAccessLog {
	return predicate.KnowledgeAccessLog(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.KnowledgeAccessLog) predicate.KnowledgeAccessLog {
	return predicate.KnowledgeAccessLog(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.KnowledgeAccessLog) predicate.KnowledgeAccessLog {
	return predicate.KnowledgeAccessLog(sql.NotPredicates(p))
}
